const http = require("http");
const crypto = require("crypto");
const { WebSocketServer, WebSocket } = require("ws");

const PORT = Number(process.env.PORT || 3000);
const MAX_HISTORY = 100;
const CHAT_INTERVAL = 700;
const MINE_INTERVAL = 105;
const RACE_TARGET = 30;
const MAX_MUSIC_QUEUE = 40;
const ADMIN_TOKEN = String(process.env.ADMIN_TOKEN || "");
const PRIORITY_PRICE = String(process.env.PRIORITY_PRICE || "R$ 5,00");
const PRIORITY_PAYMENT_LINK = String(process.env.PRIORITY_PAYMENT_LINK || "");

const clients = new Map();
const messages = [];
const rooms = new Map();
const musicQueue = [];
let currentSong = null;
const leaderboards = new Map([
  ["mineracao",[]],["memoria",[]],["creeper",[]],["crafting",[]],["quiz",[]],["corrida",[]]
]);

const STATIC = {"/index.html":{"type":"text/html; charset=utf-8","data":""},"/community.html":{"type":"text/html; charset=utf-8","data":""},"/studio.html":{"type":"text/html; charset=utf-8","data":""},"/overlay.html":{"type":"text/html; charset=utf-8","data":""},"/styles.css":{"type":"text/css; charset=utf-8","data":""},"/shared.js":{"type":"application/javascript; charset=utf-8","data":""},"/community.js":{"type":"application/javascript; charset=utf-8","data":""},"/assets/emote-heart.webp":{"type":"image/webp","data":""},"/assets/aventura-evo.webp":{"type":"image/webp","data":""},"/assets/pausa-live.webp":{"type":"image/webp","data":""},"/assets/emote-surprise.webp":{"type":"image/webp","data":""},"/assets/emote-hype.webp":{"type":"image/webp","data":""},"/assets/emote-crown.webp":{"type":"image/webp","data":""},"/assets/live-interativa.webp":{"type":"image/webp","data":""}};
function staticKey(rawUrl) {
  const raw = String(rawUrl || "/").split("?")[0];
  let key;
  try { key = decodeURIComponent(raw); } catch { return null; }
  if (key === "/") key = "/index.html";
  if (!key.startsWith("/")) key = "/" + key;
  return key;
}
const server = http.createServer((req,res)=>{
  if(req.url==="/health"){
    res.writeHead(200,{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"});
    res.end(JSON.stringify({ok:true,online:clients.size,music:musicQueue.length,version:"4.0.0"}));
    return;
  }
  const key=staticKey(req.url);
  const item=key && STATIC[key];
  if(!item){res.writeHead(404,{"Content-Type":"text/plain; charset=utf-8"});res.end("Página não encontrada.");return}
  const isHtml=key.endsWith(".html");
  res.writeHead(200,{
    "Content-Type":item.type,
    "Cache-Control":isHtml?"no-cache":"public, max-age=300",
    "X-Content-Type-Options":"nosniff",
    "Referrer-Policy":"strict-origin-when-cross-origin",
    "X-Frame-Options":"SAMEORIGIN"
  });
  res.end(Buffer.from(item.data,"base64"));
});
const wss = new WebSocketServer({ server, path:"/ws" });

function cleanText(value,max){return String(value ?? "").replace(/[\u0000-\u001F\u007F]/g," ").trim().slice(0,max)}
function defaultName(){return "Minerador-"+crypto.randomBytes(2).toString("hex").toUpperCase()}
function now(){return Date.now()}
function send(ws,data){if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify(data))}
function broadcast(data, filter=()=>true){
  const payload=JSON.stringify(data);
  for(const [ws,info] of clients)if(ws.readyState===WebSocket.OPEN && filter(info,ws))ws.send(payload);
}
function presence(){broadcast({type:"presence",online:clients.size})}
function isLocalAddress(addr=""){return addr==="127.0.0.1" || addr==="::1" || addr.endsWith("127.0.0.1")}

function roomSnapshot(name){
  const room=rooms.get(name); if(!room)return null;
  return {name:room.name,target:RACE_TARGET,active:room.active,winner:room.winner||null,
    players:[...room.players.entries()].map(([id,p])=>({id,name:p.name,score:p.score}))};
}
function broadcastRoom(name){const snap=roomSnapshot(name);if(snap)broadcast({type:"race_state",room:snap},info=>info.room===name)}
function getRoom(name){
  if(!rooms.has(name))rooms.set(name,{name,active:true,winner:null,players:new Map(),resetTimer:null});
  return rooms.get(name);
}
function removeFromRoom(info){
  if(!info.room)return;
  const room=rooms.get(info.room);
  if(room){room.players.delete(info.id);broadcastRoom(room.name);if(room.players.size===0&&!room.resetTimer)rooms.delete(room.name)}
  info.room=null;
}
function addLeaderboard(game,name,score){
  if(!leaderboards.has(game))return;
  score=Math.max(0,Math.min(1000000,Number(score)||0));
  name=cleanText(name,20)||"Minerador";
  const list=leaderboards.get(game);
  const old=list.find(x=>x.name.toLowerCase()===name.toLowerCase());
  if(old)old.score=Math.max(old.score,score);
  else list.push({name,score});
  list.sort((a,b)=>b.score-a.score);
  list.splice(10);
}
function leaderboardSnapshot(){
  const out={}; for(const [k,v] of leaderboards)out[k]=v.map(x=>({...x}));
  return out;
}
function broadcastLeaderboards(){broadcast({type:"leaderboard_state",leaderboards:leaderboardSnapshot()})}
function resetRace(room){
  room.winner=null;room.active=true;
  for(const p of room.players.values())p.score=0;
  room.resetTimer=null;broadcastRoom(room.name);
  broadcast({type:"system",message:`Nova rodada iniciada na sala ${room.name}.`},i=>i.room===room.name);
}

function publicSong(s){
  return {id:s.id,title:s.title,url:s.url,requestedBy:s.requestedBy,votes:s.voters.size,
    priorityStatus:s.priorityStatus,priorityCode:s.priorityCode||"",createdAt:s.createdAt};
}
function sortedMusic(){
  return [...musicQueue].sort((a,b)=>{
    const pa=a.priorityStatus==="paid"?1:0, pb=b.priorityStatus==="paid"?1:0;
    if(pb!==pa)return pb-pa;
    if(b.voters.size!==a.voters.size)return b.voters.size-a.voters.size;
    return a.createdAt-b.createdAt;
  });
}
function musicSnapshot(){
  return {
    current:currentSong?publicSong(currentSong):null,
    queue:sortedMusic().map(publicSong),
    config:{priorityPrice:PRIORITY_PRICE,paymentLink:PRIORITY_PAYMENT_LINK,manualApproval:true}
  };
}
function broadcastMusic(){broadcast({type:"music_state",music:musicSnapshot()})}
function findSong(id){return musicQueue.find(x=>x.id===id)}
function removeSong(id){const i=musicQueue.findIndex(x=>x.id===id);if(i>=0)return musicQueue.splice(i,1)[0];return null}
function canAdmin(info){return !!info.admin}
function authAdmin(info,token){
  if(ADMIN_TOKEN){info.admin=crypto.timingSafeEqual(Buffer.from(cleanText(token,200).padEnd(ADMIN_TOKEN.length,"\0").slice(0,ADMIN_TOKEN.length)),Buffer.from(ADMIN_TOKEN))}
  else info.admin=!!info.localAdmin;
  return info.admin;
}

wss.on("connection",(ws,req)=>{
  const info={id:crypto.randomUUID(),name:defaultName(),room:null,lastChat:0,lastMine:0,admin:false,localAdmin:isLocalAddress(req.socket?.remoteAddress||"")};
  clients.set(ws,info);
  send(ws,{type:"hello",online:clients.size,history:messages,you:{id:info.id,name:info.name},music:musicSnapshot(),leaderboards:leaderboardSnapshot(),adminAvailable:!!ADMIN_TOKEN||info.localAdmin});
  presence();

  ws.on("message",(raw)=>{
    let data; try{data=JSON.parse(raw.toString())}catch(e){return}
    if(!data||typeof data!=="object")return;

    if(data.type==="set_name"){
      const n=cleanText(data.name,20); if(n)info.name=n;
      if(info.room){const room=rooms.get(info.room),p=room?.players.get(info.id);if(p){p.name=info.name;broadcastRoom(room.name)}}
      send(ws,{type:"system",message:`Nick definido como ${info.name}.`});return;
    }

    if(data.type==="chat"){
      if(now()-info.lastChat<CHAT_INTERVAL){send(ws,{type:"error",message:"Aguarde um instante antes de enviar outra mensagem."});return}
      const msg=cleanText(data.text,220);if(!msg)return;info.lastChat=now();
      const item={id:crypto.randomUUID(),name:info.name,text:msg,time:new Date().toISOString()};
      messages.push(item);while(messages.length>MAX_HISTORY)messages.shift();broadcast({type:"chat",message:item});return;
    }

    if(data.type==="join_race"){
      const roomName=(cleanText(data.room,20)||"principal").toLowerCase().replace(/[^a-z0-9áéíóúãõâêôç_-]/gi,"-").slice(0,20)||"principal";
      removeFromRoom(info);info.room=roomName;const room=getRoom(roomName);room.players.set(info.id,{name:info.name,score:0});
      send(ws,{type:"system",message:`Você entrou na corrida ${roomName}.`});broadcastRoom(roomName);return;
    }
    if(data.type==="leave_race"){removeFromRoom(info);return}
    if(data.type==="mine"){
      if(!info.room||now()-info.lastMine<MINE_INTERVAL)return;info.lastMine=now();
      const room=rooms.get(info.room);if(!room||!room.active)return;const p=room.players.get(info.id);if(!p)return;
      p.name=info.name;p.score=Math.min(RACE_TARGET,p.score+1);
      if(p.score>=RACE_TARGET){
        room.active=false;room.winner=info.name;addLeaderboard("corrida",info.name,1);
        broadcast({type:"race_winner",name:info.name,room:room.name},i=>i.room===room.name);
        broadcastLeaderboards();
        if(room.resetTimer)clearTimeout(room.resetTimer);room.resetTimer=setTimeout(()=>resetRace(room),5000);
      }
      broadcastRoom(room.name);return;
    }

    if(data.type==="leaderboard_submit"){
      const game=cleanText(data.game,20),score=Number(data.score)||0;
      if(leaderboards.has(game)){addLeaderboard(game,info.name,score);broadcastLeaderboards()}
      return;
    }

    if(data.type==="music_add"){
      if(musicQueue.length>=MAX_MUSIC_QUEUE){send(ws,{type:"error",message:"A fila de músicas está cheia no momento."});return}
      const title=cleanText(data.title,80),url=cleanText(data.url,240);
      if(!title||!/^https?:\/\//i.test(url)){send(ws,{type:"error",message:"Informe o nome da música e um link válido."});return}
      const priorityRequested=!!data.priorityRequested;
      const song={id:crypto.randomUUID(),title,url,requestedBy:info.name,voters:new Set([info.id]),
        priorityStatus:priorityRequested?"pending":"none",priorityCode:priorityRequested?crypto.randomBytes(3).toString("hex").toUpperCase():"",createdAt:Date.now()};
      musicQueue.push(song);broadcastMusic();
      send(ws,{type:"music_added",song:publicSong(song),priorityRequested,config:musicSnapshot().config});
      return;
    }
    if(data.type==="music_vote"){
      const song=findSong(cleanText(data.id,80));if(!song)return;
      if(song.voters.has(info.id))song.voters.delete(info.id);else song.voters.add(info.id);
      broadcastMusic();return;
    }

    if(data.type==="admin_auth"){
      const ok=authAdmin(info,data.token||"");send(ws,{type:"admin_status",ok});return;
    }
    if(data.type==="music_admin"){
      if(!canAdmin(info)){send(ws,{type:"error",message:"Ação restrita ao Studio autorizado."});return}
      const action=cleanText(data.action,30),id=cleanText(data.id,80);
      if(action==="approve_priority"){const s=findSong(id);if(s)s.priorityStatus="paid"}
      else if(action==="reject_priority"){const s=findSong(id);if(s)s.priorityStatus="none"}
      else if(action==="remove")removeSong(id);
      else if(action==="play"){
        const s=removeSong(id);if(s)currentSong=s;
      } else if(action==="next"){
        const next=sortedMusic()[0];if(next){removeSong(next.id);currentSong=next}
      } else if(action==="clear_current"){currentSong=null}
      broadcastMusic();return;
    }
    if(data.type==="ping")send(ws,{type:"pong",time:Date.now()});
  });

  ws.on("close",()=>{removeFromRoom(info);clients.delete(ws);presence()});
});

server.listen(PORT,()=>{
  console.log(`LULUDAMOBILETE online em http://localhost:${PORT}`);
  console.log(`WebSocket: ws://localhost:${PORT}/ws`);
  console.log(`Prioridade musical: ${PRIORITY_PRICE} | pagamento ${PRIORITY_PAYMENT_LINK?"configurado":"não configurado"}`);
});